def fetch_json(url: str, timeout: int = 10) -> object:
    request = urllib.request.Request(url, headers={"Accept": "application/json"})
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return json.load(response)


def bounded_int(params: dict, key: str, default: int, maximum: int) -> int:
    value = int(params.get(key, default))
    if value < 1 or value > maximum:
        raise GatewayError(f"{key} must be between 1 and {maximum}")
    return value


def systems_inventory(_: dict) -> object:
    raw = run(["ssh", "proxmox", "pvesh get /cluster/resources --type vm --output-format json"])
    resources = json.loads(raw)
    return [
        {
            "id": item.get("vmid"), "name": item.get("name"), "type": item.get("type"),
            "status": item.get("status"), "node": item.get("node"),
            "cpu": item.get("cpu"), "memory": item.get("mem"), "max_memory": item.get("maxmem"),
        }
        for item in resources
    ]


def systems_services(_: dict) -> object:
    units = ["litellm", "anthropic-proxy", "litellm-https-proxy", "beeper-server", "icloud-mcp"]
    raw = run(["ssh", "exo-services", f"systemctl is-active {' '.join(units)}"])
    states = raw.splitlines()
    return dict(zip(units, states, strict=False))


def systems_host(params: dict) -> object:
    target = str(params.get("target", ""))
    if target not in HOSTS:
        raise GatewayError(f"target must be one of: {', '.join(HOSTS)}")
    alias = HOSTS[target]
    hostname = run(["ssh", alias, "hostname"], timeout=10).strip()
    uptime = run(["ssh", alias, "uptime"], timeout=10).strip()
    return {"target": target, "hostname": hostname, "uptime": uptime}


def systems_container_plan(_: dict) -> object:
    next_id = run(["ssh", "proxmox", "pvesh get /cluster/nextid"]).strip()
    storage_raw = run([
        "ssh", "proxmox",
        "pvesh get /nodes/pve/storage --content rootdir --enabled 1 --output-format json",
    ])
    template_raw = run([
        "ssh", "proxmox",
        "pvesh get /nodes/pve/storage/local/content --content vztmpl --output-format json",
    ])
    bridge_raw = run([
        "ssh", "proxmox",
        "pvesh get /nodes/pve/network --type bridge --output-format json",
    ])
    storages = [
        {"storage": item.get("storage"), "type": item.get("type"), "active": item.get("active")}
        for item in json.loads(storage_raw)
    ]
    templates = [item.get("volid") for item in json.loads(template_raw)]
    bridges = [
        {"iface": item.get("iface"), "active": item.get("active"), "address": item.get("address")}
        for item in json.loads(bridge_raw)
    ]
    return {"next_id": int(next_id), "storages": storages, "templates": templates, "bridges": bridges}


def scheduler_status(_: dict) -> object:
    active = run(["systemctl", "--user", "is-active", "deepseek-harness-web.service"]).strip()
    timers = run(["systemctl", "list-timers", "--all", "--no-legend", "--no-pager"])
    lines = [line for line in timers.splitlines() if line.strip()]
    return {
        "dsh_service": active,
        "system_timer_count": len(lines),
        "system_timers": lines[:30],
        "hermes_cron_status": (run(["hermes", "cron", "status"]).strip() if shutil.which("hermes") else "hermes not installed"),
        "hermes_jobs": (run(["hermes", "cron", "list"]).strip() if shutil.which("hermes") else "[]"),
    }


def beeper_recent(params: dict) -> object:
    args = ["beeper-recent", "--limit", str(bounded_int(params, "limit", 20, 50))]
    include_preview = params.get("include_preview", params.get("previews", False))
    if not isinstance(include_preview, bool):
        raise GatewayError("include_preview must be a boolean")
    if include_preview:
        args.append("--include-preview")
    scope = params.get("scope", "active")
    if scope not in {"active", "all"}:
        raise GatewayError("scope must be active or all")
    args.extend(["--scope", scope, "--interaction-days", str(bounded_int(params, "interaction_days", 180, 365))])
    networks = params.get("networks", [])
    if not isinstance(networks, list) or not all(isinstance(item, str) and item for item in networks):
        raise GatewayError("networks must be an array of non-empty account IDs")
    if networks:
        args.extend(["--networks", ",".join(networks)])
    return remote_helper(args)


def beeper_thread(params: dict) -> object:
    thread = str(params.get("thread", ""))
    return remote_helper(["beeper-thread", "--thread", thread, "--limit", str(bounded_int(params, "limit", 20, 50))])


def beeper_chat_metadata(params: dict) -> object:
    thread = str(params.get("thread", "")).strip()
    if not thread or len(thread) > 300:
        raise GatewayError("thread must be one exact Beeper chat ID")
    encoded = urllib.parse.quote(thread, safe="")
    data = remote_beeper_get(f"/v1/chats/{encoded}?maxParticipantCount=20")
    chat = data.get("chat", data) if isinstance(data, dict) else {}
    raw_participants = chat.get("participants", []) if isinstance(chat, dict) else []
    if isinstance(raw_participants, dict):
        raw_participants = list(raw_participants.values())
    allowed = {"id", "username", "fullName", "profileName", "isBot", "isNetworkBot", "cannotMessage"}
    participants = []
    for participant in raw_participants if isinstance(raw_participants, list) else []:
        if isinstance(participant, dict):
            participants.append({key: participant[key] for key in allowed if key in participant})
    return {
        "chat_id": chat.get("id", chat.get("chatID", thread)),
        "account_id": chat.get("accountID", chat.get("accountId")),
        "network": chat.get("network"),
        "type": chat.get("type"),
        "title": chat.get("title"),
        "participants": participants,
        "available_fields": sorted(str(key) for key in chat.keys()),
    }


