def run(command: list[str], timeout: int = 30) -> str:
    result = subprocess.run(command, capture_output=True, text=True, timeout=timeout, check=False)
    output = result.stdout[:MAX_OUTPUT]
    if result.returncode != 0:
        error = (result.stderr or output or f"exit {result.returncode}")[:2_000]
        raise GatewayError(error.strip())
    return output


def remote_helper(arguments: list[str], timeout: int = 60) -> object:
    command = " ".join(shlex.quote(item) for item in [
        "python3", "/home/rgsaura/bin/personal-services-read.py", *arguments,
    ])
    # Prefer CT126's stable LAN address from AI Hub.  The `exo-services`
    # Tailscale alias may require an interactive reauthentication flow, which
    # would make otherwise bounded agent reads hang or fail unexpectedly.
    raw = run(["ssh", "192.168.100.225", command], timeout=timeout)
    payload = json.loads(raw)
    if not payload.get("ok"):
        raise GatewayError(payload.get("error", "personal service read failed"))
    return payload.get("data")


def remote_beeper_get(path: str, timeout: int = 30) -> object:
    if not path.startswith("/v1/") or any(char in path for char in "\r\n"):
        raise GatewayError("invalid Beeper API path")
    encoded_path = base64.urlsafe_b64encode(path.encode()).decode()
    script = """
