    if raw.startswith("BEEPER_TOKEN="):
        token = raw.split("=", 1)[1].strip().strip("\\\"'")
        break
if not token:
    raise SystemExit("Beeper token unavailable")
request = urllib.request.Request(
    "http://127.0.0.1:23374" + path,
    headers={"Accept": "application/json", "Authorization": "Bearer " + token},
)
with urllib.request.urlopen(request, timeout=20) as response:
    print(json.dumps({"ok": True, "data": json.load(response)}))
""".strip()
    command = " ".join(shlex.quote(item) for item in [
        "env", f"EXO_BEEPER_PATH={encoded_path}", "python3", "-c", script,
    ])
        raise GatewayError("query must be 1-200 characters")
    path = (
        f"/v1/accounts/{urllib.parse.quote(account, safe='')}/contacts"
        f"?query={urllib.parse.quote(query, safe='')}&limit={bounded_int(params, 'limit', 10, 20)}"
    )
    data = remote_beeper_get(path)
    raw_items = data.get("items", []) if isinstance(data, dict) else []
    allowed = {"id", "username", "fullName", "profileName", "isBot", "isNetworkBot", "cannotMessage"}
    items = []
    for item in raw_items if isinstance(raw_items, list) else []:
        if isinstance(item, dict):
            items.append({key: item[key] for key in allowed if key in item})
    return {"account_id": account, "items": items}


def beeper_search(params: dict) -> object:
    query = str(params.get("query", ""))
    scope = params.get("scope", "active")
    if scope not in {"active", "all"}:
        raise GatewayError("scope must be active or all")
    networks = params.get("networks", [])
    if not isinstance(networks, list) or not all(isinstance(item, str) and item for item in networks):
        raise GatewayError("networks must be an array of non-empty account IDs")
    args = [
        "beeper-search", "--query", query,
        "--limit", str(bounded_int(params, "limit", 20, 50)),
        "--scope", scope,
        "--interaction-days", str(bounded_int(params, "interaction_days", 180, 365)),
    ]
    if networks:
        args.extend(["--networks", ",".join(networks)])
    return remote_helper(args)


